    e.preventDefault(); canvas.setPointerCapture(e.pointerId);
    const p = at(e);
    if (tool === "pick") { const d = ctx.getImageData(p.x | 0, p.y | 0, 1, 1).data; setColor("#" + [d[0], d[1], d[2]].map((v) => v.toString(16).padStart(2, "0")).join("")); setTool("brush"); return; }
    remember(); dirty = true;
    if (tool === "fill") { flood(p.x | 0, p.y | 0, color); return; }
